head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > getDeletedData]<br/>Row 의 상태가 '삭제' 또는 '제거' 인 Row 데이터를 2차원 배열로 반환합니다.",
    "validation" : [
        "필터와 정렬이 적용된 상태를 기준으로 Row 상태값이 'D', 'V', 'E' 인 Row 데이터가 반환됩니다.",
        "반환값으로 필터와 정렬이 적용된 상태를 기준으로 Row 상태가 '삭제' 또는 '제거' 인 데이터를 2차원 배열로 반환합니다.",         
        "Row 의 상태값이 'D', 'V', 'E' 인 Row 가 반환되며, 'E' 상태인 Row 는 필터링 여부와 관계없이 항상 포함됩니다. ",
        "반환되는 배열은 정렬이 적용된 순서대로 생성되며 'E' 상태인 Row 는 마지막에 생성됩니다.",
        "DataList 모듈에 필터가 적용되지 않은 경우 전체 Row 데이터를 기준으로 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);

    target1.deleteRow(4);
};



scwin.btn_deleteRow_onclick = function (e) {
    target1.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(2, "col1", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow(3);
}



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})
    target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("col1", 1);
};



scwin.btn_getDeletedData_onclick = function (e) {
    let rtn = target1.getDeletedData();  

    for (var i=0; i < rtn.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue(`row[${i}] : ${rtn[i]}`);
    }    
};
